import itertools
def _ev(s, M, ix):
    op = s[0]
    if op == 'not': return not _ev(s[1], M, ix)
    if op == 'and': return all(_ev(x, M, ix) for x in s[1:])
    if op == 'or': return any(_ev(x, M, ix) for x in s[1:])
    a, b = ix[s[1]], ix[s[2]]
    if op == 'all': return all(r[b] for r in M if r[a])
    if op == 'no': return not any(r[a] and r[b] for r in M)
    if op == 'some': return any(r[a] and r[b] for r in M)
    if op == 'somenot': return any(r[a] and not r[b] for r in M)
    raise ValueError(op)
def _models(T, P):
    # a model = the set of non-empty Venn regions; every named class is non-empty
    n = len(T); ix = {t: i for i, t in enumerate(T)}
    regs = [r for r in itertools.product((0, 1), repeat=n) if any(r)]
    out = []
    for mask in range(1, 1 << len(regs)):
        M = [regs[k] for k in range(len(regs)) if mask >> k & 1]
        if all(any(r[i] for r in M) for i in range(n)) and all(_ev(p, M, ix) for p in P):
            out.append(M)
    assert out, 'premises inconsistent'
    return out, ix
def _holds(c, Ms, ix):
    if c[0] == 'poss': return any(_ev(c[1], M, ix) for M in Ms)
    return all(_ev(c, M, ix) for M in Ms)
