B = [('no', 'M', 'K')]
G = ('somenot', 'C', 'M')
O = [('all', 'M', 'C'), ('no', 'C', 'K'), ('some', 'C', 'K'), ('somenot', 'K', 'C')]
def _ok(extra):
    try:
        Ms, ix = _models(T, B + [extra])
    except AssertionError:
        return False
    return _holds(G, Ms, ix)
h = [L for L, x in zip('ABCD', O) if _ok(x)]
assert len(h) == 1, h
ans = h[0]

