def _t(expr, e): return bool(eval(expr, {'imp': imp, 'iff': iff}, e))
def entails(V, P, c): return all(_t(c, e) for e in _rows(V) if all(_t(p, e) for p in P))
def equiv(V, f, g): return all(_t(f, e) == _t(g, e) for e in _rows(V))
def consistent(V, S): return any(all(_t(s, e) for s in S) for e in _rows(V))
import itertools
def regions(n):
    ch = list(itertools.combinations(range(n), 2))
    cross = lambda p, q: p[0] < q[0] < p[1] < q[1] or q[0] < p[0] < q[1] < p[1]
    X = sum(1 for p, q in itertools.combinations(ch, 2) if cross(p, q))
    V = n + X
    E = n + sum(1 + sum(1 for q in ch if cross(p, q)) for p in ch)  # arcs + chord pieces
    return E - V + 1  # faces inside the circle (Euler, minus the outer face)
assert [regions(k) for k in (1, 2, 3, 4, 5)] == [1, 2, 4, 8, 16]
